def comps_conn(g,diag):
 R,C=len(g),len(g[0]);seen=set();out=[]
 dirs=[(i,j) for i in (-1,0,1) for j in (-1,0,1) if (i,j)!=(0,0) and (diag or abs(i)+abs(j)==1)]
 for r in range(R):
  for c in range(C):
   if g[r][c]==0 and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c));co=[]
    while stack:
     x,y=stack.pop();co.append((x,y))
     for dx,dy in dirs:
      p=x+dx,y+dy
      if 0<=p[0]<R and 0<=p[1]<C and g[p[0]][p[1]]==0 and p not in seen:seen.add(p);stack.append(p)
    out.append(co)
 return out
